// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Fixed Assets: Scrap and Sell an Asset
// Hand edits: a fresh running asset is created first (the recording used one that already existed), label/field-name
// selectors, state assertions, result screenshots, wide viewport, login fallback.
// WRITES (test database only): creates + confirms one asset, one sales order, one customer invoice and sells the
// asset (the disposal entry is posted). Everything is tagged [TEST]. Posted entries cannot be removed afterwards.
import { test, expect } from "../../../../core/fixtures/index";
import { uniqueName } from "../../../../core/utils/RandomDataGenerator";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/fixed-assets-scrap-and-sell-an-asset";
const ASSET = uniqueName("Asset to sell");
const CUSTOMER = "AC005851";
const CUSTOMER_NAME = "KOLITHA THUSHARA";
const SALE_PRICE = "100000";

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Fixed Assets: Scrap and Sell an Asset @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Fixed Assets: Scrap and Sell an Asset", async ({ page, rpc }) => {
    test.setTimeout(480_000);

    // Confirming an order needs its analytic plans (Sales Center, Product Group) to map to accounts. Those accounts are
    // keyed by PRODUCT CATEGORY and WAREHOUSE, so choose a product whose category has a Product Group account, and a
    // warehouse that has a Sales Center account. The product must also invoice on ORDERED quantities (nothing ships here).
    const groupAccounts = await rpc.searchRead<{ bugfix_analytics_product_category_id: [number, string] | false }>(
      "account.analytic.account", [["plan_id.name", "=", "Product Group"]], ["bugfix_analytics_product_category_id"], { limit: 500 });
    const categories = [...new Set(groupAccounts.map((g) => g.bugfix_analytics_product_category_id && g.bugfix_analytics_product_category_id[0]).filter(Boolean))];
    const [prod] = await rpc.searchRead<{ name: string }>(
      "product.product", [["sale_ok", "=", true], ["invoice_policy", "=", "order"], ["active", "=", true], ["categ_id", "in", categories], ["company_id", "=", 2]],
      ["name"], { limit: 1 });
    expect(prod, "a sellable product whose category has a Product Group account must exist").toBeTruthy();
    const product = { name: prod.name };
    const [centre] = await rpc.searchRead<{ bugfix_analytics_warehouse_id: [number, string] }>(
      "account.analytic.account", [["plan_id.name", "=", "Sales Center"], ["bugfix_analytics_warehouse_id.company_id", "=", 2]],
      ["bugfix_analytics_warehouse_id"], { limit: 1 });
    expect(centre, "a warehouse with a Sales Center account must exist").toBeTruthy();
    const warehouseName = centre.bugfix_analytics_warehouse_id[1];

    await page.goto("/web");
    // The rpc fixture's API login can end the saved browser session — fall back to the login form.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const menu = (xmlid: string) => page.locator(`[data-menu-xmlid="${xmlid}"]`);
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const dropItem = (name: string | RegExp) => page.locator(".dropdown-menu .dropdown-item").filter({ hasText: name });
    const pickOption = async (input: Locator, text: string, optionText: string | RegExp = text) => {
      await input.click();
      await input.fill(text);
      const opt = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: optionText }).first();
      await opt.waitFor({ state: "visible", timeout: 15000 });
      await opt.click();
    };
    const openApp = async (name: string) => {
      await page.goto("/web");
      const tile = page.getByRole("option", { name, exact: true });
      await tile.waitFor({ state: "visible", timeout: 30000 });
      await tile.click();
      await expect(page.locator(".o_menu_sections")).toBeVisible({ timeout: 45000 });
    };
    const saveBtn = page.locator("button.o_form_button_save");

    // ------------------------------------------------------------------ precondition: a running asset (not a numbered step)
    await test.step("00. Precondition: create and confirm the asset to sell", async () => {
      await openApp("Accounting");
      await menu("account.menu_finance_entries").first().click();
      await menu("account_asset.menu_action_account_asset_form").first().click();
      await page.getByRole("button", { name: "New", exact: true }).first().click();
      await page.locator("#name_0").fill(ASSET);
      await pickOption(page.locator("#model_id_0"), "Factory Equipments");
      await expect(page.locator(".o_field_widget[name=account_asset_id] input")).toHaveValue(/11010170/, { timeout: 15000 });
      await page.locator("#original_value_0").fill("100000");
      await page.locator("#original_value_0").press("Tab");
      await page.locator(".o_statusbar_buttons button").filter({ hasText: /^Confirm$/ }).first().click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "asset is Running").toContainText("Running", { timeout: 30000 });
    });

    // ------------------------------------------------------------------ Part 1: the sales order
    await test.step("00b. Open the Sales app, Quotations", async () => {
      await openApp("Sales");
      await topMenu("Orders").first().click();
      await dropItem(/^Quotations$/).first().click();
      await expect(page.locator(".o_list_view, .o_kanban_view").first()).toBeVisible({ timeout: 30000 });
    });
    await run(1, "Create a new Quotation", page.getByRole("button", { name: "New", exact: true }), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "quotation form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(2, "Select the customer", page.locator(".o_field_widget[name=partner_id] input"), async (l) => {
      await pickOption(l, CUSTOMER, CUSTOMER_NAME);
      await expect(l).toHaveValue(new RegExp(CUSTOMER_NAME, "i"));
    }, true);
    await run(3, "Quotation type: Sales", page.locator("#x_studio_quotation_type_0, .o_field_widget[name=x_studio_quotation_type] select").first(), async (l) => {
      await l.selectOption({ label: "Sales" });
    }, true);
    await run(4, "Other Info", page.locator('a[name="other_information"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_field_widget[name=warehouse_id]"), "warehouse field visible").toBeVisible({ timeout: 15000 });
    }, true);
    await run(5, "Open the Warehouse field", page.locator(".o_field_widget[name=warehouse_id] input"), async (l) => { await l.click(); });
    await run(6, "Set warehouse to Production Warehouse", page.locator(".o_field_widget[name=warehouse_id] input"), async (l) => {
      await pickOption(l, warehouseName.slice(0, 20), warehouseName.slice(0, 20));
      await expect(l).toHaveValue(new RegExp(warehouseName.slice(0, 10), "i"));
    }, true);
    await run(7, "Order Lines", page.locator('a[name="order_lines"]'), async (l) => {
      await l.click();
      await expect(page.locator("td.o_field_x2many_list_row_add a").first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(8, "Add a product", page.locator("td.o_field_x2many_list_row_add a").filter({ hasText: /Add a product/ }), async (l) => {
      await l.click();
      const prod = page.locator(".o_selected_row td[name=product_template_id] input, .o_selected_row td[name=product_id] input").first();
      await pickOption(prod, product.name.slice(0, 25), product.name.slice(0, 25));
      const price = page.locator(".o_selected_row td[name=price_unit] input").first();
      await price.fill(SALE_PRICE);
      await page.locator(".o_form_view .o_form_label").first().click();
      await expect(page.locator(".o_data_row"), "one order line").toHaveCount(1);
    }, true);
    await run(9, "Confirm the quotation", page.locator(".o_statusbar_buttons button").filter({ hasText: /^Confirm$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "order is a Sales Order").toContainText(/Sales Order/i, { timeout: 30000 });
    }, true);
    await run(10, "Create Invoice", page.locator(".o_statusbar_buttons button").filter({ hasText: /^Create Invoice$/ }), async (l) => {
      await l.click();
      // Depending on the product's invoicing policy Odoo either opens the "Create invoices" wizard first or goes
      // straight to the draft invoice.
      const dlg = page.locator(".modal:visible").first();
      if (await dlg.isVisible({ timeout: 6000 }).catch(() => false)) {
        await resultShot(page, 10);
        await dlg.locator("footer button").filter({ hasText: /Create (Draft )?Invoice/ }).first().click();
        await expect(dlg).toBeHidden({ timeout: 45000 });
      }
      await expect(page.locator(".o_form_view").filter({ hasText: /Customer Invoice/ }), "draft invoice opened").toBeVisible({ timeout: 30000 });
    });
    let invoiceNumber = "";
    await run(11, "Confirm the invoice", page.locator(".o_statusbar_buttons button").filter({ hasText: /^Confirm$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "invoice is Posted").toContainText("Posted", { timeout: 30000 });
      invoiceNumber = (await page.locator(".o_form_view h1").first().innerText()).trim();
      expect(invoiceNumber, "invoice has a number").toMatch(/\//);
    }, true);

    // ------------------------------------------------------------------ Part 2: sell the asset
    await test.step("11b. Open the asset", async () => {
      await openApp("Accounting");
      await menu("account.menu_finance_entries").first().click();
      await menu("account_asset.menu_action_account_asset_form").first().click();
      const search = page.locator("input.o_searchview_input").first();
      await search.fill(ASSET.split(" ").pop() as string);
      await search.press("Enter");
      await page.locator(".o_data_row").filter({ hasText: ASSET }).first().click();
      await expect(page.locator(".o_form_view")).toBeVisible({ timeout: 30000 });
    });
    await run(12, "Modify Depreciation", page.locator(".o_statusbar_buttons button").filter({ hasText: /Modify Depreciation/ }), async (l) => {
      await l.click();
      await expect(page.locator(".modal:visible"), "wizard opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(13, "Select Sell", page.locator(".modal:visible #radio_field_0_sell, .modal:visible input[value=sell]").first(), async (l) => {
      await l.check();
      await expect(l).toBeChecked();
    }, true);
    await run(14, "Link the Customer Invoice", page.locator(".modal:visible #invoice_ids_0, .modal:visible .o_field_widget[name=invoice_ids] input").first(), async (l) => {
      await pickOption(l, invoiceNumber, invoiceNumber);
      await expect(page.locator(".modal:visible .o_field_widget[name=invoice_ids]")).toContainText(invoiceNumber);
    }, true);
    await test.step("14b. Choose the Gain Account (required on this database)", async () => {
      // Nothing fills the Gain Account in by itself here, and the wizard will not run without it. Use the disposal
      // account when it is offered, otherwise the first account Odoo suggests.
      const gain = page.locator(".modal:visible .o_field_widget[name=gain_account_id] input, .modal:visible #gain_account_id_0").first();
      await gain.click();
      await gain.fill("DISPOSAL");
      const opt = page.locator(".o-autocomplete--dropdown-item").first();
      if (!(await opt.isVisible({ timeout: 4000 }).catch(() => false))) {
        await gain.fill("");
        await gain.click();
      }
      await opt.waitFor({ state: "visible", timeout: 15000 });
      await shot(page, gain, "step-14-gain.png");
      await opt.click();
      await expect(gain, "gain account chosen").toHaveValue(/.+/);
    });
    await run(15, "Sell", page.locator(".modal:visible button").filter({ hasText: /^Sell$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".modal:visible"), "wizard closed").toBeHidden({ timeout: 45000 });
      await expect(page.locator(".o_form_view"), "disposal entry opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(16, "Post", page.locator(".o_statusbar_buttons button").filter({ hasText: /^Post$/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "disposal entry is Posted").toContainText("Posted", { timeout: 30000 });
    }, true);
    await run(17, "Asset", page.locator("button.oe_stat_button").filter({ hasText: /Asset/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "asset is Closed").toContainText(/Close/i, { timeout: 30000 });
    }, true);

    await test.step("Verify: the asset is closed", async () => {
      const [a] = await rpc.searchRead<{ state: string }>("account.asset", [["name", "=", ASSET]], ["state"], { limit: 1 });
      expect(a?.state, "asset state in the database").toBe("close");
    });
  });
});
